------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Communities].[ParentCommunityKey]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_thrive].[fnCommunitiesParentCommunityKey_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_thrive].[fnCommunitiesParentCommunityKey_GetRootID];
GO

CREATE FUNCTION [higherlogic_thrive].[fnCommunitiesParentCommunityKey_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [CommunityKey],
            [ParentCommunityKey],
            [CommunityKey] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_thrive].[Communities]
        WHERE
            [CommunityKey] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[CommunityKey],
            c.[ParentCommunityKey],
            c.[CommunityKey] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_thrive].[Communities] c
        INNER JOIN
            CTE_RootParent p ON c.[CommunityKey] = p.[ParentCommunityKey]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [ParentCommunityKey] IS NULL
    ORDER BY
        [RootParentID]
);
GO

